#!/usr/bin/env python3
"""Original MIT RBG0/RBG1 guest, ST-058 §§4.1/6.2/6.4/appendix RBG1.

SH-2 instructions populate both rotation matrices, B0 characters, B1 pattern
names, RBG0 bitmap and registers. No firmware/SDK/third-party objects.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_effects import assembler, store
HERE=Path(__file__).resolve().parent

def build():
    source='; Original MIT RBG0/RBG1 guest. Generated by build_rbg1.py.\n'
    for off,value in [(0x20,0x30),(0xE,0x203),(0x28,0),(0x2A,0x3200),
                      (0x30,0x8008),(0x3A,0x8000),(0x60,0x30),(0xB0,0),(0xF8,5),(0xFC,4),
                      (0xD0,2),(0xC0,0),(0xC2,0),(0xC4,30),(0xC6,15)]:
        source+=store(0x25F80000+off,value)
    source+=store(0x25F800BC,0x10000,'l')
    for at in [0x20000,0x20080]:
        for off in [0x10,0x14,0x4C,0x50]:source+=store(0x25E00000+at+off,0x10000,'l')
    for off,value in [(0x1C,0x10000),(0x2C,0x10000)]:
        source+=store(0x25E20000+off,value,'l') # A identity
    for off,value in [(0x20,0x10000),(0x28,0xFFFF0000),(0x48,15<<16)]:
        source+=store(0x25E20080+off,value,'l') # B (y,15-x)
    for y in range(18):
        for x in range(18):source+=store(0x25E00000+(y*512+x)*2,0x801F)
    for i in range(16):
        source+=store(0x25E40000+i*2,0x1111)
        source+=store(0x25E40020+i*2,0x2222)
    for index,value in [(0,0),(1,1),(64,1),(65,0)]:
        source+=store(0x25E60000+index*2,value)
    source+=store(0x25F00002,0x7C00)+store(0x25F00004,0x3E0)
    source+=store(0x25F80000,0x8000)
    source+=store(0x0600A100,0x600D,'l')+'park:\nsleep\nbra park\nnop\n'
    code=assembler.assemble(source,base=0x200)
    assert len(code)<0x10000
    rom=bytearray(524288)
    rom[:8]=struct.pack('>II',0x200,0x06100000)
    rom[0x200:0x200+len(code)]=code
    lines=['# Original MIT RBG0/RBG1 BIOS fixture. Adjacent LICENSE.',
           '# Generated from rbg1.s by build_rbg1.py; unspecified bytes zero.']
    for at in range(0,len(rom),16):
        chunk=rom[at:at+16]
        if any(chunk):lines.append(f'{at:04X} '+' '.join(f'{w:04X}' for w in struct.unpack('>8H',chunk)))
    return source,'\n'.join(lines)+'\n',hashlib.sha256(rom).hexdigest()

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
    source,text,digest=build()
    for path,value in [(HERE/'rbg1.s',source),(HERE/'rbg1.hex',text)]:
        if args.check:assert path.read_text()==value,f'Rebuild {path.name}'
        else:path.write_text(value)
    print(f'{"Verified" if args.check else "Built"} rbg1.hex; expanded ROM SHA-256 {digest}')
